import click
import time
import fnmatch
import json as json_mod
import logging
from logging.handlers import RotatingFileHandler
from pathlib import Path
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

def setup_file_logger(path: str) -> logging.Logger:
    logger = logging.getLogger("filewatch.events")
    logger.setLevel(logging.INFO)
    handler = RotatingFileHandler(path, maxBytes=10*1024*1024, backupCount=5)
    handler.setFormatter(logging.Formatter("%(asctime)s %(message)s"))
    logger.addHandler(handler)
    return logger

class PatternHandler(FileSystemEventHandler):
    def __init__(self, pattern: str, fmt: str = "text", file_logger: logging.Logger | None = None):
        self.pattern = pattern
        self.fmt = fmt
        self.file_logger = file_logger
        self.events: list[dict] = []

    def on_any_event(self, event):
        if event.is_directory:
            return
        if self.pattern and not fnmatch.fnmatch(Path(event.src_path).name, self.pattern):
            return
        entry = {"type": event.event_type, "path": event.src_path, "ts": time.time()}
        self.events.append(entry)
        if self.fmt == "json":
            line = json_mod.dumps(entry)
        else:
            line = f"[{event.event_type}] {event.src_path}"
        click.echo(line)
        if self.file_logger:
            self.file_logger.info(line)

