import json
import re
from collections import Counter
from pathlib import Path

import click

def parse_text_log(path: str) -> list[dict]:
    """Parse text-format log lines like: 2026-03-31 10:00:00,000 [created] /path/to/file"""
    events = []
    pattern = re.compile(r"\d{4}-\d{2}-\d{2} [\d:,]+ \[(\w+)\] (.+)$")
    with open(path) as f:
        for line in f:
            m = pattern.match(line.strip())
            if m:
                events.append({"type": m.group(1), "path": m.group(2)})
    return events

def parse_json_log(path: str) -> list[dict]:
    events = []
    with open(path) as f:
        for line in f:
            # Strip timestamp prefix from RotatingFileHandler
            idx = line.find("{")
            if idx >= 0:
                try:
                    events.append(json.loads(line[idx:]))
                except json.JSONDecodeError:
                    continue
    return events

def parse_log(path: str) -> list[dict]:
    """Auto-detect format and parse."""
    with open(path) as f:
        first = f.readline()
    if "{" in first:
        return parse_json_log(path)
    return parse_text_log(path)

@click.command()
@click.argument("log_path", type=click.Path(exists=True))
@click.option("--top", default=10, help="Number of top files to show")
def summary(log_path: str, top: int):
    """Print statistics from a filewatch log file."""
    events = parse_log(log_path)
    if not events:
        click.echo("No events found in log.")
        return

    click.echo(f"Total events: {len(events)}")
    click.echo("\nEvents by type:")
    type_counts = Counter(e["type"] for e in events)
    for etype, count in type_counts.most_common():
        click.echo(f"  {etype}: {count}")

    click.echo(f"\nTop {top} most-changed files:")
    file_counts = Counter(e["path"] for e in events)
    for fpath, count in file_counts.most_common(top):
        click.echo(f"  {count:>4}  {fpath}")

