import threading

class PatternHandler(FileSystemEventHandler):
    def __init__(self, pattern, fmt="text", file_logger=None, debounce_ms=200):
        self.pattern = pattern
        self.fmt = fmt
        self.file_logger = file_logger
        self.debounce_s = debounce_ms / 1000.0
        self.events: list[dict] = []
        self._pending: dict[str, threading.Timer] = {}
        self._lock = threading.Lock()

    def _emit(self, entry: dict):
        self.events.append(entry)
        if self.fmt == "json":
            line = json_mod.dumps(entry)
        else:
            line = f"[{entry['type']}] {entry['path']}"
        click.echo(line)
        if self.file_logger:
            self.file_logger.info(line)

    def on_any_event(self, event):
        if event.is_directory:
            return
        if self.pattern and not fnmatch.fnmatch(Path(event.src_path).name, self.pattern):
            return
        entry = {"type": event.event_type, "path": event.src_path, "ts": time.time()}
        key = event.src_path
        with self._lock:
            if key in self._pending:
                self._pending[key].cancel()
            timer = threading.Timer(self.debounce_s, self._emit, args=[entry])
            self._pending[key] = timer
            timer.start()

