import threading

class StatsReporter:
    def __init__(self, handler: PatternHandler, interval: float = 5.0):
        self.handler = handler
        self.interval = interval
        self._stop = threading.Event()
        self._thread = threading.Thread(target=self._run, daemon=True)

    def start(self) -> None:
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()

    def _run(self) -> None:
        while not self._stop.wait(self.interval):
            count = len(self.handler.events)
            click.echo(f"[stats] {count} events recorded")

